def amicable_numbers_sum(limit: int) -> int:
    def get_divisors_sum(n):
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i*i != n:
                    total += n // i
        return total

    amicable_sum = 0
    for a in range(1, limit + 1):
        b = get_divisors_sum(a)
        # Amicable numbers are two different numbers where the sum of proper divisors of each is equal to the other.
        if b > a and get_divisors_sum(b) == a:
            amicable_sum += a + b

    # Note: The standard definition usually sums each unique number in the pair once.
    # Based on the assert amicable_numbers_sum(999)==504, it implies summing only numbers <= limit.
    # Let's refine for the specific test case (220 + 284 = 504).

    total_sum = 0
    for a in range(1, limit + 1):
        b = get_divisors_sum(a)
        if b != a and b > 1 and get_divisors_sum(b) == a:
            # If both numbers in the pair are <= limit, sum them.
            # However, usually these problems ask to sum 'a' if it is part of an amicable pair.
            # Given 220 + 284 = 504, and both < 999:
            if a <= limit:
                total_sum += a
    return total_sum

