def jacobsthal_num(n):
    # 嚴格遵循輸入契約 (Formal Input Contract)
    if not isinstance(n, int) or n < 0:
        raise ValueError("invalid inputs")

    a, b = 0, 1  # a 代表 J_{i}, b 代表 J_{i+1}

    for _ in range(n):
        a, b = b, b + 2 * a

    return a
