def max_sum_increasing_subseq(a: list, n: int, index: int, k: int) -> float | int:
    """
    Find the maximum sum of an increasing subsequence from a[0...index] 
    that can be extended by including a[k], where index < k.
    """
    # dp[i] represents the max sum of an increasing subsequence ending at index i
    dp = [x for x in a[:index + 1]]

    for i in range(1, index + 1):
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + a[i])

    # Find the maximum sum among all subsequences ending at some i <= index 
    # such that a[i] < a[k]. If no such i exists, the result is just a[k].
    max_prev_sum = 0
    for i in range(index + 1):
        if a[i] < a[k]:
            max_prev_sum = max(max_prev_sum, dp[i])

    return max_prev_sum + a[k]
```

