def max_sum_increasing_subseq(a, n, index, k):
    t = a[k]
    dp = [0] * n
    mx = 0
    for i in range(index + 1):
        if a[i] < t:
            s = a[i]
            for j in range(i):
                if a[j] < a[i]:
                    s = max(s, dp[j] + a[i])
            dp[i] = s
            mx = max(mx, s)
    return mx + t
```

